using System.Collections;using UnityEngine;public class BouncingBall : MonoBehaviour{    [SerializeField] private float bounceForce = 10f;    [SerializeField] private float speedThreshold = 2f;    [SerializeField] private Color highSpeedColor = Color.green;    [SerializeField] private Color lowSpeedColor = Color.red;    private Rigidbody rb;    private Renderer ballRenderer;    private bool isBelowThreshold = false;    private void Start()    {        rb = GetComponent<Rigidbody>();        ballRenderer = GetComponent<Renderer>();        ballRenderer.material.color = highSpeedColor;    }    private void FixedUpdate()    {        float currentSpeed = rb.linearVelocity.magnitude;        if (currentSpeed < speedThreshold && !isBelowThreshold)        {            StartCoroutine(LowSpeedTracker());        }    }    private void OnCollisionEnter(Collision collision)    {        Vector3 velocity = rb.linearVelocity;        velocity.y = bounceForce;        rb.linearVelocity = velocity;    }    private IEnumerator LowSpeedTracker()    {        isBelowThreshold = true;        ballRenderer.material.color = lowSpeedColor;        float lowSpeedDuration = 0f;        do        {            yield return null;            lowSpeedDuration += Time.deltaTime;        }
        while (rb.linearVelocity.magnitude < speedThreshold);        ballRenderer.material.color = highSpeedColor;        isBelowThreshold = false;        Debug.Log($"Время нахождения на низкой скорости: {lowSpeedDuration:F2} сек.");    }}